def summarize_expenses(records):
    totals = {}
    for category, amount in records:
        totals[category] = totals.get(category, 0) + amount
    ordered = sorted(totals.items(), key=lambda kv: (-kv[1], kv[0]))
    return [[c, a] for c, a in ordered]

